complex_multi_model.pipe.source:
pipeline complex_multi_model {
    load "students.csv";
    drop id, notes;
    select cgpa, attendance, study_hours, exam_score;
    split train = 70%;
    split test = 30%;
    train m_dead = logistic_regression;
    train m1 = decision_tree;
    evaluate m1;
    train m2 = random_forest;
    evaluate m2;
}

complex_redundant.pipe.source:
pipeline complex_redundant {
    load "students.csv";
    clean missing_values;
    clean missing_values;
    select cgpa, attendance, study_hours, col_a, col_b;
    select cgpa, attendance, study_hours, col_a, col_b;
    drop col_a;
    drop col_b;
    split train = 80%;
    train dead_model = logistic_regression;
    train live_model = decision_tree;
    evaluate live_model;
    train trailing_model = random_forest;
}

complex_valid_drop_chain.pipe.source:
pipeline complex_valid_drop_chain {
